    import openpyxl
    def scarica(sc, formato, sub=None):
        pg.click('text=Esporta in Excel'); pg.wait_for_selector('.modale'); pg.check('input[value=%s]' % sc)
        if sub: pg.select_option('#esporta-sub', label=sub)
        pg.click('[data-formato=%s]' % formato)
        with pg.expect_download() as d: pg.click('.modale-piede >> text=Scarica')
        pg.wait_for_timeout(300)
        dst=os.path.join(S, 'esportato_' + d.value.suggested_filename); d.value.save_as(dst)
        return d.value.suggested_filename, dst
    def esporta(sc, sub=None):
        pg.click('text=Esporta in Excel'); pg.wait_for_selector('.modale'); pg.check('input[value=%s]' % sc)
        if sub: pg.select_option('#esporta-sub', label=sub)
        pg.click('[data-formato=xlsx]')
        with pg.expect_download() as d: pg.click('.modale-piede >> text=Scarica')
        pg.wait_for_timeout(200)
        dst=os.path.join(S, 'esportato_' + d.value.suggested_filename); d.value.save_as(dst)
        return d.value.suggested_filename, openpyxl.load_workbook(dst)
